export async function drawRectangle(page, startX, startY, endX, endY) {
    await page.getByTestId("toolbar-rectangle").click({ force: true });
    await page.mouse.move(startX, startY);
    await page.mouse.down();
    await page.mouse.move(endX, endY, { steps: 10 });
    await page.mouse.up();
}

export async function drawEllipse(page, startX, startY, endX, endY) {
    await page.getByTestId("toolbar-ellipse").click({ force: true });
    await page.mouse.move(startX, startY);
    await page.mouse.down();
    await page.mouse.move(endX, endY, { steps: 10 });
    await page.mouse.up();
}

